local Players = game:GetService("Players")local Player = Players.LocalPlayerlocal ScreenGui = Instance.new("ScreenGui")local MenuFrame = Instance.new("Frame")local ToggleButton = Instance.new("TextButton")local MainButton = Instance.new("TextButton")  -- Nút chính để bật tắt menu-- Thiết lập GUIScreenGui.Parent = Player:WaitForChild("PlayerGui")MenuFrame.Size = UDim2.new(0, 300, 0, 200)MenuFrame.Position = UDim2.new(0.5, -150, 0.5, -100)MenuFrame.BackgroundColor3 = Color3.new(1, 1, 1)MenuFrame.BorderSizePixel = 0MenuFrame.Visible = false  -- Bắt đầu với menu không hiển thịMenuFrame.Parent = ScreenGuiToggleButton.Size = UDim2.new(0, 100, 0, 50)ToggleButton.Position = UDim2.new(0.5, -50, 0.2, 0)ToggleButton.Text = "Toggle Menu"ToggleButton.Parent = MenuFrameMainButton.Size = UDim2.new(0, 100, 0, 50)MainButton.Position = UDim2.new(0.5, -50, 0.1, 0)MainButton.Text = "Show/Hide Menu"MainButton.Parent = ScreenGuilocal colors = {    Color3.fromRGB(255, 0, 0),    Color3.fromRGB(255, 127, 0),    Color3.fromRGB(255, 255, 0),    Color3.fromRGB(0, 255, 0),    Color3.fromRGB(0, 0, 255),    Color3.fromRGB(75, 0, 130),    Color3.fromRGB(148, 0, 211),}local menuVisible = false-- Hàm để thay đổi màu viềnlocal function changeBorderColor()    local currentIndex = 1    while true do        if menuVisible then            MenuFrame.BorderColor3 = colors[currentIndex]            currentIndex = currentIndex + 1            if currentIndex > #colors then                currentIndex = 1            end        end        wait(0.3)  -- Thay đổi tốc độ chuyển màu ở đây    endend-- Nút Toggle - để ẩn/hiện menuMainButton.MouseButton1Click:Connect(function()    menuVisible = not menuVisible    MenuFrame.Visible = menuVisibleend)-- Bắt đầu thay đổi màuchangeBorderColor()